function schemaInput(f,r){if(f.type==='race')return field(f.label,'v_'+f.id,'select',r?.values?.[f.id]||'',true,op(db.records.raceDefinitions.filter(x=>raceSelectable(x,r))));if(f.type==='stat')return field(f.label,'v_'+f.id,'number',r?.values?.[f.id]??0,true);if(['catalog','catalogmulti'].includes(f.type)){let category=db.categories.find(c=>c.name===f.catalog||c.id===f.catalog);let race=raceOf(r)?.id;let entries=db.records.catalogs.filter(x=>inCategory(x,category)&&raceMatch1513(x,race)&&variantMatch1513(x,race,r?.variant,r?.secondaryVariant));return field(f.label,'v_'+f.id,f.type==='catalog'?'select':'multiselect',r?.values?.[f.id]??'',f.required,op(entries))}return base_schemaInput(f,r)}
