function auditLabel(k){let f=Object.values(db.schemas).flatMap(s=>s.flatMap(g=>g.fields)).find(x=>x.id===k);return f?.label||AUDIT_LABELS[k]||NAMES[k]||String(k).replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,x=>x.toUpperCase())}
