function ageField1510(){let fs=db.schemas.sheets.flatMap(x=>x.fields);return fs.find(f=>f.key==='age1510'&&['number','text'].includes(f.type))||fs.find(f=>f.label.trim().toLowerCase()==='edad'&&['number','text'].includes(f.type));}
function ageValue1510(r,f){let v=r.values?.[f?.id];return (typeof v==='number'||typeof v==='string'&&v.trim()!=='')&&Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null;}
function ageEligible1510(r){return approved('sheets',r)&&r.lifeState!=='Fallecido definitivamente';}
function agePlan1510(f){return db.records.sheets.filter(ageEligible1510).filter(r=>ageValue1510(r,f)!==null);}
function timeHours1510(v,allowZero=false){let factors={horas:1,dias:24,semanas:168,meses:720,anos:8640};if(v.elapsedAmount===undefined||String(v.elapsedAmount).trim()===''||!Object.hasOwn(factors,v.elapsedUnit))throw Error('Indica cuánto tiempo ha transcurrido y selecciona la unidad.');let n=Number(v.elapsedAmount),h=n*factors[v.elapsedUnit];if(!Number.isFinite(n)||n<0||!Number.isSafeInteger(h)||(!allowZero&&h===0))throw Error('Introduce un tiempo válido, expresable en horas enteras.');return h;}
function timeFields1510(allowZero=true){return `<div class="card"><h3>Tiempo transcurrido dentro del rol</h3><p class="muted">${allowZero?'Indica 0 si no ha pasado tiempo.':'Indica una duración mayor que cero.'} Se usan meses de 30 días y años de 12 meses.</p><div class="grid">${field('Cantidad','elapsedAmount','number','',true)}${field('Unidad','elapsedUnit','select','',true,[{value:'horas',label:'Horas'},{value:'dias',label:'Días'},{value:'semanas',label:'Semanas'},{value:'meses',label:'Meses'},{value:'anos',label:'Años'}])}</div></div>`;}
function timeText1510(h){let parts=[];for(let [n,singular,plural] of [[8640,'año','años'],[720,'mes','meses'],[24,'día','días'],[1,'hora','horas']]){let q=Math.floor(h/n);if(q)parts.push(q+' '+(q===1?singular:plural));h%=n;}return parts.join(', ')||'0 horas';}
