function ageCompute1510(h){let f=ageField1510();if(!h)return {f,ids:new Set(),total:Number(db.settings.years1510)||0};if(!f)throw Error('No existe un campo de edad numérico en el molde de fichas.');let selected=agePlan1510(f);if(selected.length>400)throw Error('El avance supera el límite de 400 fichas por operación. No se ha modificado ninguna.');let old=Number(db.settings.years1510)||0;if(!Number.isSafeInteger(ageHours1510(old)+h)||selected.some(r=>!Number.isSafeInteger(ageHours1510(ageValue1510(r,f))+h)))throw Error('La edad resultante supera el límite numérico.');return {f,ids:new Set(selected.map(r=>r.id)),total:Number(((ageHours1510(old)+h)/8640).toFixed(10))};}
