function ageAdvance1510(){if(!allow('sagas','manage')||!controlAllowed('ageAdvance1510',[]))throw Error('Sin permiso para avanzar el tiempo.');let f=ageField1510();if(!f)throw Error('No existe un campo de edad numérico en el molde de fichas.');let total=agePlan1510(f).length,skipped=db.records.sheets.filter(ageEligible1510).length-total;dialog('Avanzar tiempo del rol',`<p class="block">Se actualizará la edad de las fichas aprobadas vigentes. Los fallecidos definitivamente quedan excluidos.</p><p class="muted">${total} fichas con edad válida · ${skipped} sin edad válida.</p>`+timeFields1510(false)+field('Confirmo el avance de tiempo y la actualización de las edades','confirmAge','checkbox',false)+reasonField(),v=>{let h=timeHours1510(v),reason=auditReason(v);if(!v.confirmAge)throw Error('Confirma el avance temporal.');if(!originalOwner(me)&&!reason)throw Error('El motivo es obligatorio.');let p=ageCompute1510(h);return commit14([['records','sheets'],['settings','years1510']],a=>{ageApply1510(a[0],p,h);a[1]=p.total;},'Avance temporal del rol: +'+timeText1510(h)+' · '+p.ids.size+' fichas',reason);},{label:'Aplicar avance'});}
function sagasPage(){let a=activeSaga(),list=[...db.records.sagas].reverse();return head('Historial de sagas','Etapas del rol y reglas vigentes en cada momento.',permitted('sagas','manage','Iniciar saga','sagaStart',[],'primary')+permitted('sagas','manage','Avanzar tiempo','ageAdvance1510',[]))+`<div class="card"><div class="row"><div><h2>${a?E(a.name):'Sin saga activa'}</h2><p>${sagaRuleSummary(sagaRules(db.settings.rules))}</p><p>Tiempo transcurrido desde la activación del sistema: ${E(ageText1510(db.settings.years1510||0))}</p>${a?`<p class="muted">Desde ${date(a.started)}</p>`:''}</div>${a?permitted('sagas','manage','Finalizar saga','sagaFinish',[]):''}</div></div>`+(list.length?list.map(x=>{let reports=db.records.training.filter(r=>r.sagaContext?.sagaId===x.id);return `<div class="card"><div class="row"><div><h2>${E(x.name)} ${badge(x.ended?'Finalizada':'En curso',x.ended?'#9aaabe':'#75d8a5')}</h2><p class="muted">${date(x.started)} — ${x.ended?date(x.ended):'Actualidad'}</p></div><div class="actions">${btn('Consultar historial','sagaView',[x.id])}${permitted('sagas','manage','Editar información','sagaEdit',[x.id])}</div></div>${x.elapsedHours1510!==undefined?`<p>Tiempo transcurrido al iniciar: ${E(timeText1510(x.elapsedHours1510))}</p>`:''}${x.description?`<p class="block">${E(x.description)}</p>`:''}<p>${sagaRuleSummary(x.revisions.at(-1)?.rules)}</p><p class="muted">${x.revisions.length} versiones de reglas · ${reports.length} informes registrados</p></div>`}).join(''):empty('Todavía no se ha registrado ninguna saga.'))}
function sagaStart(){if(!requirePerm('sagas','manage'))return;let r=db.settings.rules;dialog('Iniciar saga',field('Nombre de la saga','name','text','',true)+field('Descripción','description','textarea','')+field('Umbral de estadísticas base','softCap','number',r.softCap,true)+field('Divisor de ganancias desde el umbral','divisor','number',r.divisor,true)+timeFields1510()+(activeSaga()?'<p class="muted">La saga actual se finalizará automáticamente al iniciar la nueva.</p>':'')+field('Confirmo el tiempo transcurrido y la actualización de edades','confirmAge','checkbox',false)+reasonField(),f=>{let name=f.name.trim(),cap=+f.softCap,div=+f.divisor,reason=auditReason(f),h=timeHours1510(f,true);if(!name||!originalOwner(me)&&!reason||!Number.isFinite(cap)||cap<0||!Number.isFinite(div)||div<1)throw Error('Introduce un nombre, motivo y parámetros válidos.');if(!f.confirmAge)throw Error('Confirma el tiempo transcurrido.');if(h&&!controlAllowed('ageAdvance1510',[]))throw Error('Sin permiso para avanzar el tiempo.');let p=ageCompute1510(h),stamp=now();return transaction([['settings'],['records','sagas'],['records','sheets']],([settings,sagas,sheets])=>{let previous=sagas.find(x=>!x.ended);if(previous){previous.ended=stamp;previous.closedBy=actor();previous.closeReason=reason}settings.rules.softCap=cap;settings.rules.divisor=div;settings.years1510=p.total;ageApply1510(sheets,p,h);sagas.push({id:uid(),name,description:f.description,elapsedHours1510:h,started:stamp,ended:null,createdBy:actor(),revisions:[sagaRevision(settings.rules,reason)]})},'Inicio de saga: '+name+' · Tiempo transcurrido: '+timeText1510(h),reason)})}
