function old14_safeUndo(l){let paths=l.paths||[l.path],bs=l.paths?l.before:[l.before];return paths.every((p,i)=>{if(!p||!p.length||['logs','faqs'].includes(p[0])||(p[0]==='records'&&(p.length===1||p[1]==='bugs')))return false;if(p[0]==='settings'&&(p.length===1||p[1]==='invitationCodes')){let before=p.length===1?bs[i]?.invitationCodes:bs[i];let current=db.settings.invitationCodes;if(JSON.stringify(before)!==JSON.stringify(current))return false;}if(p[0]==='users')return p.length===1&&JSON.stringify(protectedUsers(bs[i]))===JSON.stringify(protectedUsers(db.users));if(p[0]==='roles')return p.length===1&&JSON.stringify(bs[i]?.find(x=>x.id==='owner'))===JSON.stringify(db.roles.find(x=>x.id==='owner'));return true})}
