function faqTopics(k,rows){let consumed=new Set(),topics=[];for(let row of rows){if(consumed.has(row))continue;let spec=FAQ13_TOPICS[k]?.find(x=>x[1].includes(row[0]));let parts=spec?rows.filter(r=>spec[1].includes(r[0])&&!consumed.has(r)): [row];for(let r of parts)consumed.add(r);topics.push({title:parts.length>1?spec[0]:row[0],group:row[2]?.group||'General',parts})}return topics}
function faqBody(k){let rows=faqRows(k),topics=faqTopics(k,rows),groups=new Map();for(let t of topics){if(!groups.has(t.group))groups.set(t.group,[]);groups.get(t.group).push(t)}return `<p class="muted">${topics.length} temas disponibles para este perfil.</p>${[...groups].map(([name,entries])=>`<section class="faqgroup"><h2 class="faqtitle">${E(name)}</h2>${entries.map(t=>{let links=[...new Set(t.parts.flatMap(faqLinks))];return `<details class="card faqentry" data-filter><summary><b>${E(t.title)}</b></summary>${t.parts.map(r=>`<div class="faq-part">${k==='faqStaff'&&t.parts.length>1?`<h3>${E(r[0])}</h3>`:''}<p class="block">${E(r[1])}</p></div>`).join('')}${links.length?`<div class="faq-links">${links.map(k=>`<button type="button" class="faq-link" data-faq-nav="${E(k)}">${E(faqLinkLabel(k))}<span aria-hidden="true"> ↗</span></button>`).join('')}</div>`:''}</details>`}).join('')}</section>`).join('')||empty('No hay preguntas disponibles para este perfil.')}`}
function faqPreviewRoles(k){return db.roles.filter(r=>r.id!=='owner'&&!!r.perms?.[k]?.view&& (r.perms[k].data?.content??true))}
function faqSelectedRole(k){if(!isOwner())return '';let choices=faqPreviewRoles(k);let saved=sessionStorage.getItem(SESSION+'_faq_'+k);if(!saved||saved==='self')return 'self';if(choices.some(r=>r.id===saved))return saved;return choices.find(r=>r.id==='verifier')?.id||choices[0]?.id||''}
function faqPreview(k,roleId){let prev=me;if(roleId==='self')return faqBody(k);if(!faqPreviewRoles(k).some(r=>r.id===roleId))return empty('Selecciona un rango con acceso a esta guía.');try{me={...prev,roles:[roleId]};return faqBody(k)}finally{me=prev}}
function faqPage(k){if(!allow(k))return empty('No tienes acceso a esta guía.');let profile=faqProfile(),name=db.roles.find(r=>r.id===profile)?.name||'Staff';let role=faqSelectedRole(k),choices=faqPreviewRoles(k);return head(k==='faqStaff'?'FAQ de Staff'+(isOwner()?'':' · '+name):'FAQ de usuarios',isOwner()&&k==='faqStaff'?'Consulta cómo se presenta el manual a cada rango de Staff.':'Guía de uso de las funciones disponibles.',isOwner()&&!viewMode()?btn('Editar preguntas','faqEdit',[],'primary'):'')+(isOwner()?`<div class="card faq-preview-card"><label for="faqpreview">Visualizar como rango</label><select id="faqpreview"><option value="self" ${role==='self'?'selected':''}>Mi cuenta · todas las preguntas</option>${choices.map(r=>`<option value="${E(r.id)}" ${r.id===role?'selected':''}>${E(r.name)}</option>`).join('')}</select>${!choices.length&&k==='faqStaff'?'<p class="muted">No hay rangos de Staff con acceso al manual.</p>':''}</div>`:'')+searchBox()+`<div id="faqbody">${isOwner()?faqPreview(k,role):faqBody(k)}</div>`}
function faqBind(){let p=$('#faqpreview'),f=$('#filter');if(p)p.onchange=()=>{if(!isOwner())return;sessionStorage.setItem(SESSION+'_faq_'+view,p.value);$('#faqbody').innerHTML=faqPreview(view,p.value);if(f)f.oninput()};if(f)f.oninput=()=>{let q=f.value.trim().toLocaleLowerCase();document.querySelectorAll('#faqbody .faqentry').forEach(el=>el.hidden=!el.textContent.toLocaleLowerCase().includes(q));document.querySelectorAll('#faqbody .faqgroup').forEach(g=>g.hidden=![...g.querySelectorAll('.faqentry')].some(e=>!e.hidden))}}
function faqOwnerOnlyRequirement083(r){return /^bugs(?::|$)/.test(r)||/^[^:]+:action:(?:dataBrowse|dataEdit|orphanDelete|renameUser|userPassword|deleteUser|deleteLogs|selectLogs|faqEdit)$/.test(r)}
function faqRequirementOptions(){let rows=[];for(let [k,n] of allPermissionModules()){rows.push([k,n+' · Acceso']);for(let [key,label] of dataDefinitions(k))rows.push([k+':data:'+key,n+' · Dato: '+label]);for(let [key,label] of controlsFor(k))rows.push([k+':action:'+key,n+' · Acción: '+label]);for(let key of (PAGE_ACTIONS[k]||ACTIONS))rows.push([k+':perm:'+key,n+' · Permiso: '+(ACTLABEL[key]||key)])}return rows.filter(([r])=>!faqOwnerOnlyRequirement083(r))}
function faqEdit(){if(!isOwner()||!['faqStaff','faqUser'].includes(view))return;let k=view,entries=clone(db.faqs[k]||[]),idx=0,sync=()=>{};let opts=faqRequirementOptions(),profileOpts=[...(k==='faqUser'?[['member','Miembro']]:[]),['coowner','Co-Owner'],['admin','Admin'],['verifier','Verificador'],['tester','Tester'],['@custom','Otros perfiles']];dialog('Editar '+NAMES[k],'<p class="muted">Selecciona los rangos que necesitan la pregunta. El Owner tiene acceso automático a todas. El Co-Owner también ve todo el FAQ de Staff, sin que esto cambie sus permisos de ejecución. Sin rangos seleccionados, la pregunta se muestra a quienes tengan acceso al FAQ y cumplan todos los requisitos.</p><div class="two"><div><label>Seleccionar pregunta</label><select id="faq-select" size="9" style="min-height:240px"></select><div class="actions"><button type="button" id="faq-add">Añadir</button><button type="button" id="faq-up">↑</button><button type="button" id="faq-down">↓</button><button type="button" id="faq-del" class="danger">Eliminar</button></div></div><div id="faq-editor"></div></div>',()=>{sync();if(entries.some(([q,a,m])=>!q.trim()||!a.trim()||!m.group.trim()))throw Error('Cada pregunta necesita sección, título y respuesta.');return remoteFaq(k,entries)},{wide:true,bind:root=>{let sel=root.querySelector('#faq-select'),editor=root.querySelector('#faq-editor');let paintList=()=>{sel.innerHTML=entries.map(([q,a,m],i)=>`<option value="${i}" ${i===idx?'selected':''}>${E((m?.group||'General')+' · '+(q||'Nueva pregunta'))}</option>`).join('')};let paint=()=>{paintList();let row=entries[idx];if(!row){editor.innerHTML='<p class="muted">Añade una pregunta.</p>';sync=()=>{};return}let [q,a,m]=row;m??={group:'General',roles:[],requires:[]};row[2]=m;let reqs=[...new Map([...opts,...m.requires.filter(r=>!opts.some(o=>o[0]===r)).map(r=>[r,'Requisito antiguo (no disponible): '+r])]).entries()];editor.innerHTML=`<label>Sección</label><input id="faq-section" value="${E(m.group)}"><label>Pregunta</label><input id="faq-question" value="${E(q)}"><label>Respuesta</label><textarea id="faq-answer" rows="10">${E(a)}</textarea>${faqLinksEditor(m)}<label>Perfiles destinatarios (ninguno = todos los autorizados)</label><div class="sub">${profileOpts.map(([id,n])=>`<label style="display:inline-flex;gap:6px;margin:5px"><input type="checkbox" data-faq-role="${id}" ${m.roles.includes(id)?'checked':''}>${E(n)}</label>`).join('')}</div><label>Requisitos simultáneos de acceso, datos y acciones</label><div id="faq-reqs">${m.requires.map((r,i)=>`<div class="row"><span>${E(reqs.find(o=>o[0]===r)?.[1]||r)}</span><button type="button" data-remove-req="${i}">×</button></div>`).join('')}</div><select id="faq-req-pick"><option value="">Seleccionar requisito…</option>${reqs.filter(([r])=>!m.requires.includes(r)).map(([r,n])=>`<option value="${E(r)}">${E(n)}</option>`).join('')}</select><button type="button" id="faq-req-add">Añadir requisito</button>`;sync=()=>{entries[idx]=[editor.querySelector('#faq-question').value,editor.querySelector('#faq-answer').value,{group:editor.querySelector('#faq-section').value,roles:[...editor.querySelectorAll('[data-faq-role]:checked')].map(e=>e.dataset.faqRole),requires:m.requires.slice(),...(editor.querySelector('#faq-auto-links').checked?{}:{links:[...editor.querySelector('#faq-links-select').selectedOptions].map(o=>o.value)})}]};editor.querySelector('#faq-auto-links').onchange=e=>editor.querySelector('#faq-links-select').disabled=e.target.checked;editor.querySelector('#faq-req-add').onclick=()=>{let v=editor.querySelector('#faq-req-pick').value;sync();if(v&&!entries[idx][2].requires.includes(v))entries[idx][2].requires.push(v);paint()};editor.querySelectorAll('[data-remove-req]').forEach(b=>b.onclick=()=>{sync();entries[idx][2].requires.splice(+b.dataset.removeReq,1);paint()})};sel.onchange=()=>{let next=+sel.value;sync();idx=next;paint()};root.querySelector('#faq-add').onclick=()=>{sync();entries.push(['','',{group:'General',roles:[],requires:[]}]);idx=entries.length-1;paint()};for(let [id,d] of [['faq-up',-1],['faq-down',1]])root.querySelector('#'+id).onclick=()=>{sync();if(idx+d>=0&&idx+d<entries.length){move(entries,idx,d);idx+=d;paint()}};root.querySelector('#faq-del').onclick=()=>{sync();if(entries.length&&confirm('¿Eliminar esta pregunta?')){entries.splice(idx,1);idx=Math.max(0,Math.min(idx,entries.length-1));paint()}};paint()}})}
function faqLog(l){return (l.paths||[l.path||[]]).some(p=>p[0]==='faqs')}
function upgrade10(d){if(d.version>=10)return;upgrade9(d);let reference={version:7,roles:[],faqs:faqDefaults()};upgrade9(reference);let old=d.faqs||{};d.faqs=clone(FAQ10_DEFAULTS);for(let k of ['faqUser','faqStaff'])for(let row of old[k]||[]){if(!reference.faqs[k].some(r=>r[0]===row[0]&&r[1]===row[1]))d.faqs[k].push([row[0],row[1],{group:'Preguntas anteriores · revisar destinatarios',roles:['owner'],requires:[]}])}d.version=10}


const BUG_TYPES=['Inicio de sesión y cuenta','Fichas y razas','Estadísticas y entrenamientos','Técnicas, maestros y catálogos','Economía, tienda e inventario','Comunidad','Navegación y apariencia','Permisos y administración','Rendimiento o carga','Otro'];
const BUG_LEVELS=['Baja','Media','Alta'];
const BUG_STATES=['Pendiente','En revisión','En marcha','Solucionado','Descartado'];
function bugStaff(){return originalOwner(me)}
function bugCan(action){return bugStaff()&&allow('bugs')&&dataAllowed('bugs','content')&&controlAllowed(action,[])}
function bugSubmit(){if(!me)return;let section=NAMES[view]||view;dialog('Reportar un error',`<p class="muted">Describe un problema de la web. No incluyas contraseñas, códigos de acceso ni información privada.</p>${field('Tipo de error','type','select','',true,BUG_TYPES)}${field('Título','title','text','',true)}${field('Descripción del error','description','textarea','',true)}${field('Pasos para reproducirlo','steps','textarea','')}${field('Resultado esperado','expected','textarea','')}${field('Captura (opcional)','image','image','')}`,f=>{if(!me||!BUG_TYPES.includes(f.type))throw Error('Selecciona un tipo válido.');let title=f.title.trim(),description=f.description.trim();if(!title||!description||title.length>150||description.length>10000)throw Error('Título de hasta 150 caracteres y descripción de hasta 10.000 caracteres.');if([f.steps,f.expected].some(v=>v.length>10000))throw Error('Los detalles no pueden superar 10.000 caracteres.');if(!withinLimit('bugs'))return false;let report={id:uid(),owner:me.id,author:me.name,created:now(),section,type:f.type,title,description,steps:f.steps.trim(),expected:f.expected.trim(),image:safeurl(f.image)?f.image:'',priority:null,status:'Pendiente',approved:false,history:[]};let ok=mutate(['records','bugs'],a=>a.unshift(report),'Reporte de error · '+title,'',false);if(ok)toast('Reporte enviado al Staff.');return ok},{label:'Enviar reporte'})}
function bugBadge(b){return badge(b.status,({'Pendiente':'#9aaabe','En revisión':'#e5b85a','En marcha':'#69b4e9','Solucionado':'#67c594','Descartado':'#e28b6f'})[b.status])}
function priorityBadge(p){return badge(p||'Sin clasificar',({'Baja':'#67c594','Media':'#e5b85a','Alta':'#e28b6f'})[p])}
function bugPage(){if(!bugStaff()||!allow('bugs')||!dataAllowed('bugs','content'))return empty('Acceso restringido.');let items=db.records.bugs;return head('Reportes de errores','Bandeja privada de incidencias de la web.')+`<div class="grid"><div class="card"><small>Sin revisar</small><div class="number">${items.filter(b=>b.status==='Pendiente').length}</div></div><div class="card"><small>En revisión / en marcha</small><div class="number">${items.filter(b=>['En revisión','En marcha'].includes(b.status)).length}</div></div><div class="card"><small>Prioridad alta sin resolver</small><div class="number">${items.filter(b=>b.priority==='Alta'&&!['Solucionado','Descartado'].includes(b.status)).length}</div></div></div><div class="card"><div class="grid">${field('Estado','bugFilterState','select','',false,BUG_STATES)}${field('Gravedad','bugFilterPriority','select','',false,['Sin clasificar',...BUG_LEVELS])}${field('Tipo','bugFilterType','select','',false,BUG_TYPES)}</div>${searchBox()}</div><div id="bug-list">${items.map(b=>`<article class="card bugcard" data-filter data-status="${E(b.status)}" data-priority="${E(b.priority||'Sin clasificar')}" data-type="${E(b.type)}"><div class="bugmeta">${bugBadge(b)}${priorityBadge(b.priority)}${b.approved?badge('Aprobado','#67c594'):''}</div><h3>${E(b.title)}</h3><p class="muted">${E(b.type)}${dataAllowed('bugs','author')?' · '+E(userName(b.owner)):''}${dataAllowed('bugs','date')?' · '+E(date(b.created)):''}</p>${dataAllowed('bugs','description')?`<p class="bugdesc">${E(b.description.slice(0,220))}${b.description.length>220?'…':''}</p>`:''}<div class="actions">${btn('Ver reporte','bugDetail',[b.id])}${bugCan('bugPriority')?btn('Gravedad','bugPriority',[b.id]):''}${bugCan('bugDismiss')&&!b.approved&&b.status!=='Descartado'?btn('Desestimar','bugDismiss',[b.id]):''}${isOwner()&&!b.approved?btn('Aprobar','bugApprove',[b.id],'primary'):''}${isOwner()?btn('Estado','bugStatus',[b.id])+btn('Eliminar','bugDelete',[b.id],'danger'):''}</div></article>`).join('')||empty('No hay reportes de errores.')}</div>`}
function bugBind(){let s=$('[name=bugFilterState]'),p=$('[name=bugFilterPriority]'),t=$('[name=bugFilterType]'),f=$('#filter');if(!s||!p||!t||!f)return;let update=()=>document.querySelectorAll('#bug-list .bugcard').forEach(el=>el.hidden=!!((s.value&&s.value!==el.dataset.status)||(p.value&&p.value!==el.dataset.priority)||(t.value&&t.value!==el.dataset.type)||!el.textContent.toLowerCase().includes(f.value.trim().toLowerCase())));s.onchange=p.onchange=t.onchange=f.oninput=update}
function bugDetail(id){if(!bugCan('bugDetail'))return;let b=record('bugs',id);if(!b)return;show(b.title,`<div class="bugmeta">${bugBadge(b)}${priorityBadge(b.priority)}${b.approved?badge('Aprobado','#67c594'):''}</div><p><b>Tipo:</b> ${E(b.type)}</p>${b.tester159?`<p><b>Reporte de pruebas:</b> ${E(b.id)}</p>`:''}${dataAllowed('bugs','author')?`<p><b>Autor:</b> ${E(userName(b.owner))} (#${E(b.owner)})</p>`:''}${dataAllowed('bugs','date')?`<p><b>Fecha:</b> ${E(date(b.created))}</p>`:''}${dataAllowed('bugs','description')?`<p><b>Apartado:</b> ${E(b.section)}</p><h3>Descripción</h3><p class="bugdesc">${E(b.description)}</p><h3>Pasos para reproducirlo</h3><p class="bugdesc">${E(b.steps||'No indicados')}</p><h3>Resultado esperado</h3><p class="bugdesc">${E(b.expected||'No indicado')}</p>${imageHTML(b.image)}`:''}${dataAllowed('bugs','history')?`<h3>Historial de revisión</h3>${b.history.map(h=>`<div class="sub"><b>${E(h.action)}</b><p class="muted">${E(h.actor.name)} · ${E(date(h.at))}</p><p class="bugdesc">${E(h.before)} → ${E(h.after)}</p><p class="bugdesc">${E(h.reason)}</p></div>`).join('')||empty('Todavía no hay revisiones.')}`:''}`)}
function bugUpdate(id,action,key,value,reason){let b=record('bugs',id);if(!b)throw Error('El reporte ya no existe.');if(!originalOwner(me)&&!reason)throw Error('Indica un motivo.');return mutate(['records','bugs'],a=>{let n=a.find(x=>x.id===id),before=n[key]??'Sin clasificar';n[key]=value;n.history.push({at:now(),actor:actor(),action,before:String(before),after:String(value),reason})},action+' · '+b.title,reason,false)}
function bugPriority(id){if(!bugCan('bugPriority'))return;let b=record('bugs',id);if(!b)return;dialog('Asignar gravedad',`<p class="muted">Baja: detalle menor. Media: afecta una función, pero hay alternativa. Alta: impide una función importante o compromete datos.</p>${field('Gravedad','priority','select',b.priority||'',true,BUG_LEVELS)}${reasonField()}`,f=>{if(!bugCan('bugPriority')||!BUG_LEVELS.includes(f.priority))throw Error('Acción no autorizada.');return bugUpdate(id,'Gravedad del reporte','priority',f.priority,auditReason(f))})}
function bugDismiss(id){if(!bugCan('bugDismiss'))return;let b=record('bugs',id);if(!b||b.approved||b.status==='Descartado')return;dialog('Desestimar reporte',`<p>El reporte seguirá en el historial como Descartado. Úsalo únicamente para reportes sin sentido, duplicados comprobados o troleo.</p>${reasonField()}`,f=>{let live=record('bugs',id);if(!bugCan('bugDismiss')||!live||live.approved||live.status==='Descartado')throw Error('No puedes desestimar este reporte.');return bugUpdate(id,'Reporte desestimado','status','Descartado',auditReason(f))})}
function bugApprove(id){if(!isOwner())return;let b=record('bugs',id);if(!b||b.approved)return;withReason('Aprobar reporte',r=>{if(!isOwner()||!originalOwner(me)&&!r)throw Error('Acción no autorizada o motivo vacío.');return mutate(['records','bugs'],a=>{let n=a.find(x=>x.id===id);if(!n||n.approved)throw Error('Reporte no disponible.');let before=n.status;n.approved=true;if(['Pendiente','Descartado'].includes(n.status))n.status='En revisión';n.history.push({at:now(),actor:actor(),action:'Reporte aprobado',before:'Sin aprobación · '+before,after:'Aprobado · '+n.status,reason:r})},'Reporte aprobado · '+b.title,r,false)})}
function bugStatus(id){if(!isOwner())return;let b=record('bugs',id);if(!b)return;dialog('Cambiar estado',field('Estado','status','select',b.status,true,BUG_STATES.slice(1))+reasonField(),f=>{if(!isOwner()||!BUG_STATES.slice(1).includes(f.status))throw Error('Estado no autorizado.');return bugUpdate(id,'Estado del reporte','status',f.status,auditReason(f))})}
function bugDelete(id){if(!isOwner())return;let b=record('bugs',id);if(!b)return;dialog('Eliminar reporte definitivamente',`<p>Se eliminará «${E(b.title)}» de la bandeja, incluido su historial. No se puede deshacer.</p>${reasonField()}`,f=>{if(!isOwner()||!originalOwner(me)&&!auditReason(f))throw Error('Motivo obligatorio.');return mutate(['records','bugs'],a=>a.splice(a.findIndex(x=>x.id===id),1),'Eliminar reporte · '+b.title,auditReason(f),false)},{label:'Eliminar definitivamente'})}
function invitationStatus(c,at=Date.now()){if(!c.enabled)return 'Desactivado';if(c.expires&&Date.parse(c.expires)<=at)return 'Caducado';if(c.starts&&Date.parse(c.starts)>at)return 'Programado';if(c.maxUses!==0&&c.uses.length>=c.maxUses)return 'Agotado';return 'Disponible'}
function invitationExplicitRoles1511(c){return Array.isArray(c?.roles)?[...new Set(c.roles)]:c?.role?[c.role]:[]}
function invitationRoles1511(c){let ids=invitationExplicitRoles1511(c);return ids.length?ids:defaultRoles1513()}
function invitationRoleNames1511(c){return (invitationExplicitRoles1511(c).length?'':'Predeterminado: ')+invitationRoles1511(c).map(id=>db.roles.find(r=>r.id===id)?.name||'Rango inexistente').join(', ')}
function validInvitation(raw){let c=db.settings.invitationCodes.find(c=>c.code===String(raw||'').trim());if(!c||invitationStatus(c)!=='Disponible'||!invitationRoles1511(c).every(id=>id!=='owner'&&db.roles.some(r=>r.id===id)))throw Error('Código de invitación no válido o no disponible.');return c}
function inviteCan(act){return settingsFull()&&allow('settings','manage')&&controlAllowed(act,[])}
function invitationPanel(){if(!settingsFull()||!dataAllowed('settings','content'))return '';return `<div class="card"><div class="head"><div><h2>Invitaciones</h2><p class="muted">Códigos de acceso con vigencia, límites e historial individual.</p></div>${inviteCan('inviteEdit')?btn('Crear código','inviteEdit',[],'primary'):''}</div>${table(['Código','Rangos','Estado','Usos','Caducidad','Acciones'],db.settings.invitationCodes.map(c=>[`<span class="invcode">${E(c.code)}</span>${c.note?'<div class="muted">'+E(c.note)+'</div>':''}`,E(invitationRoleNames1511(c)),badge(invitationStatus(c),invitationStatus(c)==='Disponible'?'#67c594':'#e5b85a'),`${c.uses.length} / ${c.maxUses||'Sin límite'}`,c.expires?E(date(c.expires)):'Sin caducidad',[inviteCan('inviteView')?btn('Detalles','inviteView',[c.id]):'',inviteCan('inviteEdit')?btn('Editar','inviteEdit',[c.id]):'',inviteCan('inviteToggle')?btn(c.enabled?'Desactivar':'Activar','inviteToggle',[c.id]):'',inviteCan('inviteDelete')?btn('Eliminar','inviteDelete',[c.id],'danger'):''].join('')]))}</div>`}
function localDateInput(v){if(!v)return '';let d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function randomInvite(){return Array.from(crypto.getRandomValues(new Uint8Array(12)),n=>n.toString(16).padStart(2,'0')).join('').toUpperCase().match(/.{1,6}/g).join('-')}
function inviteRoles157(){let rank=Math.min(...me.roles.map(id=>db.roles.findIndex(r=>r.id===id)));return db.roles.filter((r,i)=>r.id!=='owner'&&(isOwner()||i>rank));}function inviteEdit(id){if(!inviteCan('inviteEdit'))return;let c=db.settings.invitationCodes.find(x=>x.id===id);dialog(c?'Editar invitación':'Crear invitación',field('Código','code','text',c?.code||randomInvite(),true)+`<button type="button" id="new-invite-code">Generar código aleatorio</button>`+field('Etiqueta / nota interna','note','text',c?.note||'')+`<input type="hidden" name="inviteVersion1511" value="15.11" required><div class="field"><label>Rangos al registrarse</label><p class="muted">Marca uno o varios rangos. Si no marcas ninguno, se aplicará el rango predeterminado (${E(defaultRoles1513().map(id=>db.roles.find(r=>r.id===id)?.name||id).join(', ')||'Sin definir')}).</p>${inviteRoles157().map(r=>field(r.name,'inviteRole1511_'+r.id,'checkbox',invitationExplicitRoles1511(c).includes(r.id))).join('')}</div>`+field('Límite de usos (0 = ilimitado)','maxUses','number',c?.maxUses??1,true)+field('Disponible desde (opcional)','starts','datetime-local',localDateInput(c?.starts))+field('Caduca el (opcional)','expires','datetime-local',localDateInput(c?.expires))+field('Habilitado','enabled','checkbox',c?.enabled??true)+(c?`<p class="muted">Usos registrados: ${c.uses.length}. Cambiar el código o límite no reinicia su historial.</p>`:'')+reasonField(),f=>{if(!inviteCan('inviteEdit'))throw Error('Sin permiso.');if(f.inviteVersion1511!=='15.11')throw Error('Recarga la web para editar invitaciones.');let roles=inviteRoles157().filter(r=>f['inviteRole1511_'+r.id]===true).map(r=>r.id);if(!(roles.length?roles:defaultRoles1513()).every(id=>inviteRoles157().some(r=>r.id===id)))throw Error('Rango de invitación no autorizado.');let code=f.code.trim(),maxUses=Number(f.maxUses),starts=f.starts?new Date(f.starts).toISOString():null,expires=f.expires?new Date(f.expires).toISOString():null,reason=auditReason(f);if(!code||code.length>100||/\s/.test(code))throw Error('Introduce un código sin espacios de hasta 100 caracteres.');if(db.settings.invitationCodes.some(x=>x.id!==id&&x.code===code))throw Error('El código ya existe.');if(!Number.isSafeInteger(maxUses)||maxUses<0)throw Error('Límite entero no negativo.');if(starts&&expires&&Date.parse(starts)>=Date.parse(expires))throw Error('La caducidad debe ser posterior a la fecha de inicio.');if(!originalOwner(me)&&!reason)throw Error('Indica un motivo.');return mutate(['settings','invitationCodes'],a=>{let old=a.find(x=>x.id===id);let n={id:old?.id||uid(),code,roles,note:f.note.trim(),maxUses,starts,expires,enabled:!!f.enabled,uses:old?.uses||[],created:old?.created||now(),createdBy:old?.createdBy||actor(),updated:now()};if(old){delete old.role;Object.assign(old,n)}else a.push(n)},c?'Invitación editada':'Invitación creada',reason,false)},{bind:root=>{root.querySelector('#new-invite-code').onclick=()=>root.querySelector('[name=code]').value=randomInvite();root.querySelector('[name=maxUses]').min='0';root.querySelector('[name=maxUses]').step='1'}})}
function inviteView(id){if(!inviteCan('inviteView'))return;let c=db.settings.invitationCodes.find(x=>x.id===id);if(!c)return;show('Invitación',`<p class="invcode">${E(c.code)}</p><p><b>Rangos:</b> ${E(invitationRoleNames1511(c))}</p><p>${E(invitationStatus(c))} · ${c.uses.length} usos / ${c.maxUses||'Sin límite'}</p><p>Disponible desde: ${E(c.starts?date(c.starts):'Inmediata')} · Caducidad: ${E(c.expires?date(c.expires):'Sin caducidad')}</p><p>Rango asignado: ${E(db.roles.find(r=>r.id===c.role)?.name||'Predeterminado')}</p><p>Creado: ${E(date(c.created))} · ${E(c.createdBy?.name||'Sistema')}</p><p>${E(c.note)}</p><h3>Historial de usos</h3>${table(['Usuario','Fecha'],c.uses.map(u=>[E(userName(u.user)+' (#'+u.user+')'),E(date(u.at))]))}`)}
function inviteToggle(id){if(!inviteCan('inviteToggle'))return;let c=db.settings.invitationCodes.find(x=>x.id===id);if(!c)return;withReason(c.enabled?'Desactivar invitación':'Activar invitación',r=>{if(!inviteCan('inviteToggle')||!originalOwner(me)&&!r)throw Error('Motivo obligatorio.');return mutate(['settings','invitationCodes'],a=>{let n=a.find(x=>x.id===id);n.enabled=!n.enabled;n.updated=now()},'Disponibilidad de invitación modificada',r,false)})}
function inviteDelete(id){if(!inviteCan('inviteDelete'))return;let c=db.settings.invitationCodes.find(x=>x.id===id);if(!c)return;dialog('Eliminar invitación',`<p>Se eliminará el código y su historial de usos. Las cuentas ya creadas permanecerán intactas. Para conservar el historial, desactiva el código.</p>${reasonField()}`,f=>{if(!inviteCan('inviteDelete')||!originalOwner(me)&&!auditReason(f))throw Error('Motivo obligatorio.');return mutate(['settings','invitationCodes'],a=>a.splice(a.findIndex(x=>x.id===id),1),'Invitación eliminada',auditReason(f),false)},{label:'Eliminar código'})}
function upgrade11(d){if(d.version>=11)return;upgrade10(d);d.records.bugs??=[];d.settings.limits.bugs??={total:0,period:5,hours:1};d.settings.invitationCodes??=[...new Set((d.settings.codes||[]).filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim()))].map(code=>({id:uid(),code,note:'Migrado de la configuración anterior',maxUses:1,starts:null,expires:null,enabled:true,uses:[],created:now(),createdBy:{id:0,name:'Sistema'}}));delete d.settings.codes;let g=d.menu.find(([n])=>n==='Administración')||d.menu.find(([,items])=>items.some(([k])=>k==='users'));if(!g){g=['Administración',[]];d.menu.push(g)}if(!d.menu.some(([,items])=>items.some(([k])=>k==='bugs')))g[1].push(['bugs','Reportes de errores']);NAMES.bugs='Reportes de errores';for(let r of d.roles){let staff=['admin','coowner','owner'].includes(r.id);r.perms??={};r.perms.bugs={view:staff,review:staff,manage:r.id==='owner',delete:r.id==='owner',data:{content:staff,actions:staff,author:staff,date:staff,description:staff,history:staff},controls:Object.fromEntries(['bugDetail','bugPriority','bugDismiss','bugApprove','bugStatus','bugDelete'].map(k=>[k,{visible:staff&&(!['bugApprove','bugStatus','bugDelete'].includes(k)||r.id==='owner'),execute:staff&&(!['bugApprove','bugStatus','bugDelete'].includes(k)||r.id==='owner')}]))};}let add=(k,q,a,group,roles,requires)=>d.faqs[k].push([q,a,{group,roles,requires}]);add('faqUser','¿Cómo informo de un error en la web?','Pulsa Reportar un error, debajo de Cerrar sesión. Selecciona el tipo, escribe un título y describe el problema. Incluye los pasos para reproducirlo, lo que esperabas que sucediera y, si ayuda, una captura. No compartas contraseñas ni códigos. Envía un único reporte por problema; no es necesario etiquetar a nadie en Discord.','Ayuda y errores',[],[]);add('faqStaff','¿Cómo revisar un reporte de error?','Abre Reportes de errores. Usa los filtros por estado, gravedad y tipo para localizar una incidencia. Lee los pasos, intenta reproducir el error sin alterar datos reales y comprueba que no se haya reportado antes. El historial conserva autor, fecha, cambios y motivos. No publiques capturas con información privada.','Reportes de errores',[],['bugs:action:bugDetail','bugs:data:description','bugs:data:history']);add('faqStaff','¿Cómo asignar gravedad a un error?','Pulsa Gravedad y selecciona Baja (problema menor o visual), Media (afecta a una función con alternativa) o Alta (impide una función importante, riesgo de datos o acceso). Escribe el motivo. Si hay una incidencia grave y reproducible, reúne la información y notifícala al Owner; no etiquetes por cada reporte nuevo ni por errores menores.','Reportes de errores',[],['bugs:action:bugPriority']);add('faqStaff','¿Cuándo desestimar un reporte?','Desestima únicamente reportes sin sentido, troleo o duplicados comprobados. Explica por qué en el motivo. El reporte se conserva como Descartado; no desaparece de la bandeja. No desestimes un error real simplemente porque no sabes reproducirlo. Si hay dudas, conserva el reporte y aporta la información al responsable cuando proceda.','Reportes de errores',[],['bugs:action:bugDismiss']);add('faqStaff','¿Quién se encarga de la resolución de errores?','Clasifica y verifica el reporte antes de escalarlo. No etiquetes a Co-Owner solo para asignar prioridad o desestimar un reporte: puedes hacerlo tú. Si el error requiere cambiar el funcionamiento de la web o supone una incidencia grave, comunica al Owner el reporte, los pasos y su impacto. No prometas una fecha de solución.','Reportes de errores',['admin','coowner'],['bugs:action:bugPriority']);add('faqStaff','¿Cómo aprobar y actualizar un reporte?','Aprobar marca el reporte como válido y pasa los pendientes o descartados a En revisión. Estado permite marcar En revisión, En marcha, Solucionado o Descartado, con motivo registrado. Confirma la corrección antes de marcar Solucionado. Eliminar retira definitivamente el reporte de la bandeja; úsalo únicamente cuando sea necesario.','Reportes de errores',['owner'],['bugs:action:bugApprove','bugs:action:bugStatus','bugs:action:bugDelete']);add('faqStaff','¿Cómo crear y administrar códigos de invitación?','En Configuración, abre Invitaciones y pulsa Crear código. Puedes generar uno aleatorio o escribirlo, fijar una fecha de inicio y caducidad, un máximo de usos (0 = ilimitado), una nota y si está habilitado. Al registrarse con invitación obligatoria solo se aceptan códigos disponibles. Consulta Detalles para revisar los usos y desactiva un código para impedir nuevos registros sin perder su historial. Editar el límite o el código no reinicia los usos. Eliminar borra el código pero no las cuentas existentes. No compartas códigos en canales públicos.','Configuración',[],['settings:data:fullSettings','settings:action:inviteEdit','settings:action:inviteView']);d.version=11}

const FAQ12_PATCH={"¿Cómo creo mi cuenta?":{"old":"Abre el registro, introduce un nombre de usuario y una contraseña que cumpla los requisitos indicados. Si se solicita un código de invitación, pídelo por el canal de soporte. Utiliza una contraseña distinta de la de Discord.","oldMeta":{"group":"Cuenta","roles":[],"requires":[]},"drop":true,"title":"¿Cómo creo mi cuenta?","answer":"Abre el registro, introduce un nombre de usuario y una contraseña que cumpla los requisitos indicados. Si se solicita un código de invitación, pídelo por el canal de soporte. Utiliza una contraseña distinta de la de Discord.","links":null},"He perdido mi contraseña. ¿Qué hago?":{"old":"Abre un ticket de recuperación en Discord. El Staff te pedirá información sobre tu cuenta para comprobar la titularidad. Contesta todas las preguntas en el ticket privado. Si se autoriza la recuperación, recibirás instrucciones para entrar y cambiar tu contraseña. Nunca envíes tu contraseña anterior.","oldMeta":{"group":"Cuenta","roles":[],"requires":[]},"drop":true,"title":"He perdido mi contraseña. ¿Qué hago?","answer":"Abre un ticket de recuperación en Discord. El Staff te pedirá información sobre tu cuenta para comprobar la titularidad. Contesta todas las preguntas en el ticket privado. Si se autoriza la recuperación, recibirás instrucciones para entrar y cambiar tu contraseña. Nunca envíes tu contraseña anterior.","links":null},"¿Por qué no puedo acceder o registrarme?":{"old":"Lee el mensaje que aparece en pantalla. El registro puede estar cerrado, requerir invitación o existir una interrupción temporal. Si el problema persiste, abre un ticket e indica el mensaje exacto, sin compartir contraseñas.","oldMeta":{"group":"Cuenta","roles":[],"requires":[]},"drop":true,"title":"¿Por qué no puedo acceder o registrarme?","answer":"Lee el mensaje que aparece en pantalla. El registro puede estar cerrado, requerir invitación o existir una interrupción temporal. Si el problema persiste, abre un ticket e indica el mensaje exacto, sin compartir contraseñas.","links":null},"¿Dónde consulto razas, técnicas y objetos?":{"old":"En Catálogos, despliega las categorías y abre una entrada para consultar la información que esté disponible. Las categorías permiten organizar diferentes clases de contenido.","oldMeta":{"group":"Razas y aprendizaje","roles":[],"requires":["catalogs:action:contentView"]},"drop":true,"title":"¿Dónde consulto razas, técnicas y objetos?","answer":"En Catálogos, despliega las categorías y abre una entrada para consultar la información que esté disponible. Las categorías permiten organizar diferentes clases de contenido.","links":null},"¿Dónde se publican las novedades?":{"old":"En Anuncios consulta las publicaciones oficiales y sus fechas. Lee los enlaces, imágenes o instrucciones incluidos antes de participar en una actividad.","oldMeta":{"group":"Comunidad","roles":[],"requires":["announcements:data:content"]},"drop":true,"title":"¿Dónde se publican las novedades?","answer":"En Anuncios consulta las publicaciones oficiales y sus fechas. Lee los enlaces, imágenes o instrucciones incluidos antes de participar en una actividad.","links":null},"¿Qué hago si encuentro un fallo?":{"old":"Abre un ticket con el apartado, lo que intentabas hacer, el mensaje que apareció y, si es posible, una captura sin datos privados. Evita repetir una operación de compra, recompensa o registro si no sabes si se guardó.","oldMeta":{"group":"Soporte","roles":[],"requires":[]},"drop":true,"title":"¿Qué hago si encuentro un fallo?","answer":"Abre un ticket con el apartado, lo que intentabas hacer, el mensaje que apareció y, si es posible, una captura sin datos privados. Evita repetir una operación de compra, recompensa o registro si no sabes si se guardó.","links":null},"¿Cómo cambio mi contraseña?":{"old":"Abre Mi cuenta y pulsa Cambiar contraseña. Introduce la contraseña actual, la nueva y su confirmación. No compartas ninguna contraseña con otros usuarios.","oldMeta":{"group":"Cuenta","roles":[],"requires":[]},"drop":false,"title":"¿Cómo cambio mi contraseña?","answer":"En Mi cuenta, pulsa Cambiar contraseña e introduce la actual, la nueva y su confirmación. Utiliza una contraseña distinta de la de Discord. Si recibes una contraseña temporal, cámbiala antes de continuar. No compartas contraseñas ni códigos.","links":["profile"]},"¿Cómo consulto una ficha?":{"old":"Abre Fichas y busca el personaje por su nombre. Pulsa Ver para abrir los apartados que tu cuenta puede consultar. El estado indica la situación de su revisión. Una ficha pendiente no equivale a una aprobación.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets","sheets:action:formView","sheets:data:status"]},"drop":false,"title":"¿Cómo consulto una ficha?","answer":"En Fichas, busca el nombre del personaje y abre Ver. Podrás consultar sus estadísticas, habilidades, inventario y demás información autorizada. Las fichas pendientes siguen visibles; su estado no implica que estén aprobadas. Consulta la nota de revisión cuando esté disponible.","links":["sheets"]},"¿Cómo creo un personaje?":{"old":"En Fichas pulsa Crear. Rellena los campos obligatorios y elige las opciones disponibles en los selectores. El formulario solo muestra los campos que te corresponde rellenar. Guarda la ficha para enviarla a revisión.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate"]},"drop":false,"title":"¿Cómo creo un personaje?","answer":"En Fichas, pulsa Crear. Completa los campos obligatorios, elige raza y variante disponibles, y reparte sus puntos iniciales. Los apartados gestionados por Staff no aparecen en el formulario. Guarda y completa la elección de talento cuando aparezca. La ficha no está aprobada hasta que el Staff la revise; consulta su estado y corrige los datos indicados si es necesario.","links":["sheets"]},"¿Cómo elijo raza, variante y tipo de ki?":{"old":"En la creación elige primero la raza y su variante, si la tiene. El selector de tipo de ki se ajusta a esa elección y permite seleccionar uno. Los controles de ki y los tipos de ki son conceptos distintos. Las opciones que no aparecen no están disponibles para tu personaje en ese momento.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate"]},"drop":false,"title":"¿Cómo elijo raza, variante y tipo de ki?","answer":"Elige primero la raza y su variante. La web muestra únicamente las razas disponibles para tu cuenta y los tipos de ki inicial compatibles. Selecciona un solo tipo de ki. Los controles de ki son desbloqueos diferentes: una raza puede tener varios controles sin poseer varios tipos de energía. Las habilidades innatas configuradas se asignan automáticamente.","links":["sheets","catalogs"]},"¿Cómo reparto las estadísticas iniciales?":{"old":"Distribuye los puntos disponibles entre Fuerza, Velocidad, Resistencia y Ki. No introduzcas valores negativos ni superes el máximo de tu raza y variante. El poder de pelea se obtiene sumando las cuatro estadísticas. La magia se mide aparte. No hace falta calcular el total a mano.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate","sheets:data:stats"]},"drop":false,"title":"¿Cómo reparto las estadísticas iniciales?","answer":"Reparte puntos entre Fuerza, Velocidad, Resistencia y Ki. La suma es el poder de pelea inicial y no puede superar el máximo de tu variante racial. Los valores no pueden ser negativos. La magia es un porcentaje independiente. Después de crear la ficha, las estadísticas se actualizan mediante entrenamientos aprobados; no puedes editarlas por tu cuenta. El equilibrio de reparto solo se exige si el reglamento vigente lo activa.","links":["sheets","training"]},"¿Cómo se obtiene el talento?":{"old":"Al terminar de crear la ficha, elige uno de los tres resultados aleatorios ofrecidos. La elección queda guardada; no puedes repetir las tiradas para buscar otro resultado. Si todavía no lo has elegido, consulta tu personaje en Zenis e inventario.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:formCreate","wallet","wallet:data:content"]},"drop":false,"title":"¿Cómo se obtiene el talento?","answer":"Tras guardar una ficha nueva, elige uno de los tres resultados de talento que genera la web. La elección es definitiva; cerrar el selector no vuelve a sortear los resultados. Si queda pendiente, abre Zenis e inventario y utiliza Elegir talento en ese personaje.","links":["wallet","sheets"]},"¿Cómo edito mi ficha?":{"old":"Abre tu propia ficha y pulsa Editar cuando esté disponible. Modifica los datos personales que aparecen en el formulario. Los campos que no aparecen no son editables por el jugador. Si necesitas corregir un dato que no puedes cambiar, contacta con el Staff indicando el personaje y el cambio solicitado.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:formEdit"]},"drop":false,"title":"¿Cómo edito mi ficha?","answer":"Abre Fichas, localiza tu personaje y pulsa Editar. Solo aparecen los campos que puedes modificar. Raza, estadísticas, progreso, desbloqueos y demás datos gestionados por Staff no son campos de edición libre. Si detectas un dato de ese tipo incorrecto, aporta la información al Staff autorizado.","links":["sheets"]},"¿Cómo consigo técnicas y transformaciones?":{"old":"Las habilidades se obtienen mediante las reglas del rol. Consulta sus requisitos y aporta al Staff la evidencia del aprendizaje o desbloqueo. El personaje debe cumplir las condiciones aplicables; no basta con añadir un nombre en la ficha.","oldMeta":{"group":"Personajes","roles":[],"requires":["catalogs:data:content","sheets:data:progress"]},"drop":false,"title":"¿Cómo consigo técnicas y transformaciones?","answer":"Consulta los requisitos de la técnica o transformación en Catálogos. Cumple las condiciones numéricas y narrativas del reglamento y presenta la evidencia al Staff. No basta con escribir su nombre en la ficha: el desbloqueo debe quedar asignado correctamente al personaje. Los requisitos automáticos son una ayuda y no sustituyen la comprobación narrativa.","links":["catalogs","sheets","teachers"]},"¿Cómo funciona el comparador?":{"old":"Selecciona dos personajes y pulsa Comparar. Consulta los valores, diferencias y multiplicadores de cada estadística y del poder total. Una ventaja de poder no decide por sí sola el combate narrativo.","oldMeta":{"group":"Personajes","roles":[],"requires":["compare:action:compare","sheets:data:stats"]},"drop":false,"title":"¿Cómo funciona el comparador?","answer":"Selecciona dos personajes y pulsa Comparar. Cada fila muestra sus valores y la diferencia de poder correspondiente; el multiplicador indica cuántas veces un valor supera al otro. Fuerza, velocidad, resistencia y ki se comparan por separado. La ventaja estadística orienta el combate narrativo, no determina automáticamente el ganador.","links":["compare"]},"¿Qué hace el simulador de transformaciones?":{"old":"En Comparador selecciona las formas desbloqueadas que quieras simular. El resultado aplica los multiplicadores configurados sin alterar las estadísticas reales de ninguna ficha.","oldMeta":{"group":"Personajes","roles":[],"requires":["compare:action:simulatorSelect","sheets:data:stats"]},"drop":false,"title":"¿Qué hace el simulador de transformaciones?","answer":"En Comparador, elige las transformaciones disponibles para cada personaje y ejecuta la comparación. Se aplican sus multiplicadores configurados únicamente para la simulación. No concede desbloqueos ni cambia las estadísticas base.","links":["compare"]},"¿Cómo funciona la clasificación?":{"old":"Abre Clasificación desde la pestaña correspondiente y elige la estadística por la que deseas ordenar los personajes aprobados. El ranking no modifica fichas ni concede premios.","oldMeta":{"group":"Personajes","roles":[],"requires":["ranking:data:content","sheets:data:stats"]},"drop":false,"title":"¿Cómo funciona la clasificación?","answer":"Clasificación ordena las fichas aprobadas por la estadística seleccionada. El poder de pelea es la suma de las cuatro estadísticas principales; la magia se compara por separado. El ranking usa valores base, no resultados simulados de transformaciones.","links":["ranking"]},"¿Cómo propongo una raza custom?":{"old":"En Razas custom pulsa Crear. Completa el nombre, planeta de origen, descripción, características, habilidades, ventajas, desventajas, lore y demás campos solicitados. La propuesta se somete a revisión; no podrás usarla como raza disponible hasta que se apruebe y habilite.","oldMeta":{"group":"Razas y aprendizaje","roles":[],"requires":["races:action:formCreate"]},"drop":false,"title":"¿Cómo propongo una raza custom?","answer":"En Razas custom, crea una propuesta con el nombre, planeta de origen, características, habilidades, ventajas, desventajas, transformaciones y lore que solicite el molde. Revisa los requisitos del rol. La aprobación no depende de escribir un poder inicial arbitrario: el Staff determina los parámetros y su disponibilidad. Consulta el estado de la propuesta antes de usarla.","links":["races"]},"¿Cómo registro un entrenamiento?":{"old":"En Entrenamientos pulsa Registrar entrenamiento. Selecciona un personaje aprobado, el método y el lugar. Rellena duración, compañeros, evidencia y los demás datos que correspondan. Lee los requisitos antes de enviar.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]},"drop":false,"title":"¿Cómo registro un entrenamiento?","answer":"Selecciona un personaje aprobado, el método y el lugar en Entrenamientos. Lee sus requisitos y completa duración, compañeros, turnos, resultado o evidencia según el método elegido. Incluye enlaces o pruebas suficientes para que el Staff pueda comprobar lo ocurrido. Un informe enviado no equivale a una recompensa aprobada; evita duplicarlo y respeta el cooldown.","links":["training"]},"¿Cómo registro un combate?":{"old":"Los combates son métodos de entrenamiento. Selecciona el método de combate correspondiente e indica los turnos, resultado y evidencias que solicite el formulario. No dupliques un mismo enfrentamiento para obtener puntos varias veces.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]},"drop":false,"title":"¿Cómo registro un combate?","answer":"En Entrenamientos selecciona el tipo de combate correspondiente. Indica los turnos, el resultado de tu personaje, compañeros y evidencia solicitada. Debe cumplir las condiciones del combate elegido; no registres la misma actividad como combate y como entrenamiento.","links":["training"]},"¿Cuándo aumentan mis estadísticas?":{"old":"El Staff revisa tu informe y, cuando lo aprueba, aplica la recompensa a tu personaje. Consulta el estado del informe y el poder actualizado de tu ficha. Un informe enviado no concede puntos inmediatamente.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:data:status","sheets:data:stats"]},"drop":false,"title":"¿Cuándo aumentan mis estadísticas?","answer":"El Staff comprueba el informe y concede los puntos al aprobarlo. No tienes que editar las estadísticas ni crear una segunda ficha. Consulta el estado del informe y las estadísticas actualizadas de tu personaje. Si se solicita una corrección, sigue la nota de revisión en vez de reenviar informes duplicados.","links":["training","sheets"]},"¿Qué son los cooldowns y requisitos?":{"old":"Cada método tiene condiciones y un intervalo antes de poder repetirlo. Comprueba la duración, turnos, compañeros y restricciones del lugar. Si la web rechaza el envío, lee el motivo y corrige los datos o espera el tiempo necesario.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:formCreate"]},"drop":false,"title":"¿Qué son los cooldowns y requisitos?","answer":"El cooldown es el intervalo mínimo antes de repetir un método; no es su duración. Consulta los requisitos que muestra el formulario al seleccionar método y lugar. Los límites de duración, turnos, extensión narrativa y compatibilidad dependen del método. Si aparece un bloqueo, revisa sus condiciones y la fecha de la actividad anterior.","links":["training"]},"¿Cómo funciona el Spin?":{"old":"En Zenis e inventario abre el Spin de uno de tus personajes aprobados. Comprueba el precio, saldo y disponibilidad; después pulsa Girar ruleta. El importe se descuenta y los premios ordinarios se incorporan automáticamente. Los legendarios y los objetos únicos repetidos esperan revisión. No hace falta abrir un ticket por cada tirada.","oldMeta":{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinFor"]},"drop":false,"title":"¿Cómo funciona el Spin?","answer":"En Zenis e inventario, elige un personaje aprobado y abre su Spin. Comprueba el coste y el saldo antes de girar. Los premios ordinarios se incorporan automáticamente; si el resultado requiere revisión, espera la resolución sin repetir la tirada para sustituirlo. Los objetos legendarios y únicos repetidos pueden quedar pendientes. El premio pertenece al personaje seleccionado.","links":["wallet"]},"¿Cómo publico una sugerencia?":{"old":"En Sugerencias pulsa Nueva sugerencia, indica Rol, Discord o Web y explica la propuesta. Revisa el texto antes de enviarlo: una sugerencia publicada no se puede editar.","oldMeta":{"group":"Comunidad","roles":[],"requires":["suggestions:action:suggestEdit"]},"drop":false,"title":"¿Cómo publico una sugerencia?","answer":"Indica si tu propuesta se refiere a Rol, Discord o Web. Escribe un título claro, explica el problema y una solución concreta. Una sugerencia publicada no se puede editar. Si solo quieres informar de un fallo reproducible, utiliza Reportar un error, no una sugerencia.","links":["suggestions","@bug"]},"¿Cómo comento una sugerencia?":{"old":"Pulsa Comentar, escribe una aportación relacionada y revisa el texto. Los comentarios publicados permanecen. Mantén el respeto y evita repetir mensajes.","oldMeta":{"group":"Comunidad","roles":[],"requires":["suggestions:action:comment","suggestions:data:comments"]},"drop":false,"title":"¿Cómo comento una sugerencia?","answer":"Comenta únicamente información útil para debatir la propuesta. Revisa tu mensaje antes de publicarlo: no podrás eliminarlo. No dupliques comentarios ni publiques información privada.","links":["suggestions"]},"Qué comprobar antes de aprobar una ficha":{"old":"Comprueba que no falte información obligatoria, que la raza y variante sean compatibles y que el lore no contradiga las reglas. Suma Fuerza, Velocidad, Resistencia y Ki y contrasta el máximo inicial aplicable. Revisa que las habilidades iniciales y el tipo de ki correspondan. Si algo no cuadra, deja una nota concreta y no apruebes hasta que se corrija.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:stats","sheets:data:status"]},"drop":true,"title":"Qué comprobar antes de aprobar una ficha","answer":"Comprueba que no falte información obligatoria, que la raza y variante sean compatibles y que el lore no contradiga las reglas. Suma Fuerza, Velocidad, Resistencia y Ki y contrasta el máximo inicial aplicable. Revisa que las habilidades iniciales y el tipo de ki correspondan. Si algo no cuadra, deja una nota concreta y no apruebes hasta que se corrija.","links":null},"Qué hacer con una ficha que necesita correcciones":{"old":"Usa Revisar, selecciona un estado de revisión o rechazo según corresponda e indica en la nota visible los cambios concretos que necesita el jugador. No uses el estado de aprobación para una ficha incompleta. Cuando se corrija, comprueba los nuevos datos antes de aprobar.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:status"]},"drop":true,"title":"Qué hacer con una ficha que necesita correcciones","answer":"Usa Revisar, selecciona un estado de revisión o rechazo según corresponda e indica en la nota visible los cambios concretos que necesita el jugador. No uses el estado de aprobación para una ficha incompleta. Cuando se corrija, comprueba los nuevos datos antes de aprobar.","links":null},"Comprobar entrenamientos narrativos y combates":{"old":"Comprueba el método seleccionado y sus requisitos: duración, turnos, participación, resultado o extensión narrativa, según corresponda. Lee la evidencia y verifica que corresponda al personaje y al periodo declarado. Elige una recompensa que se ajuste a los hechos, sin premiar el mismo entrenamiento por duplicado.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]},"drop":true,"title":"Comprobar entrenamientos narrativos y combates","answer":"Comprueba el método seleccionado y sus requisitos: duración, turnos, participación, resultado o extensión narrativa, según corresponda. Lee la evidencia y verifica que corresponda al personaje y al periodo declarado. Elige una recompensa que se ajuste a los hechos, sin premiar el mismo entrenamiento por duplicado.","links":null},"Repartir las ganancias correctamente":{"old":"Los campos de ganancia representan puntos adicionales, no el nuevo valor total. Si un personaje tenía 20 de Fuerza y concedes 5, su Fuerza resultante será 25. Comprueba que la suma de las cuatro ganancias sea la autorizada y que el resultado de la vista previa coincida antes de guardar.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]},"drop":true,"title":"Repartir las ganancias correctamente","answer":"Los campos de ganancia representan puntos adicionales, no el nuevo valor total. Si un personaje tenía 20 de Fuerza y concedes 5, su Fuerza resultante será 25. Comprueba que la suma de las cuatro ganancias sea la autorizada y que el resultado de la vista previa coincida antes de guardar.","links":null},"Cómo comunicar una revisión al jugador":{"old":"Utiliza la nota visible para explicar qué se aprobó, qué debe corregir o por qué no procede aprobarlo. Escribe el motivo administrativo que solicite el formulario. No compartas la ganancia sugerida privada ni prometas una recompensa antes de finalizar la revisión.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]},"drop":true,"title":"Cómo comunicar una revisión al jugador","answer":"Utiliza la nota visible para explicar qué se aprobó, qué debe corregir o por qué no procede aprobarlo. Escribe el motivo administrativo que solicite el formulario. No compartas la ganancia sugerida privada ni prometas una recompensa antes de finalizar la revisión.","links":null},"Revisar fichas paso a paso":{"old":"1. Abre Fichas y localiza el personaje.\n2. Comprueba los datos obligatorios, raza y variante, tipo de ki, requisitos y reparto inicial de las cuatro estadísticas.\n3. Comprueba la coherencia del lore con el reglamento.\n4. Pulsa Revisar, selecciona el estado adecuado, añade una nota visible si necesita correcciones y escribe el motivo.\n5. Comprueba el estado guardado. Si la ficha no es válida, no la apruebes hasta que se corrija.","oldMeta":{"group":"Personajes","roles":[],"requires":["sheets:action:review","sheets:data:stats","sheets:data:status","sheets:action:formView"]},"drop":false,"title":"Revisar fichas paso a paso","answer":"1. Abre Fichas, localiza el personaje y pulsa Ver. Contrasta los campos obligatorios, raza y variante, tipo de ki, lore y disponibilidad inicial de habilidades.\n2. Suma Fuerza, Velocidad, Resistencia y Ki y comprueba el máximo racial; la magia no forma parte de esa suma. Aplica el equilibrio solo si está habilitado.\n3. Pulsa Revisar y elige el estado que corresponda. Si hay errores, usa la nota visible para especificar qué debe corregir el jugador. No apruebes hasta que cumpla el reglamento.\n4. Escribe el motivo administrativo y confirma el estado guardado. No edites estadísticas o desbloqueos como atajo de una revisión.","links":["sheets","catalogs"]},"Revisar y conceder estadísticas":{"old":"1. Abre Entrenamientos y pulsa Revisar y conceder stats.\n2. Comprueba personaje, método, lugar, requisitos, participantes, duración o turnos, resultado, evidencia y cooldown.\n3. Consulta la ganancia sugerida como referencia privada; no es una recompensa prometida.\n4. Si apruebas, reparte los puntos autorizados entre Fuerza, Velocidad, Resistencia y Ki. Comprueba el total y el poder resultante en la vista previa.\n5. Escribe el motivo y, si procede, una nota visible. Guarda. Las estadísticas se suman y el informe queda aplicado. No necesitas etiquetar a otro rango para conceder estos puntos.\nSi no cumple el reglamento, elige un estado que no apruebe y explica la corrección. No concedas puntos dos veces.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]},"drop":false,"title":"Revisar y conceder estadísticas","answer":"1. Abre Entrenamientos y localiza el informe pendiente. Comprueba personaje, método, lugar, participantes, evidencias y cooldown. En narrativos, comprueba la extensión exigida; en combates, turnos y resultado.\n2. Pulsa Revisar y conceder stats. La ganancia sugerida es una referencia privada, no una recompensa prometida.\n3. Si procede aprobar, reparte los puntos autorizados entre Fuerza, Velocidad, Resistencia y Ki. Introduce incrementos, no valores finales: si tiene 20 de Fuerza y añades 5, quedará en 25. Verifica el total y el poder resultante de la vista previa.\n4. Si no cumple, elige un estado sin aprobación. Escribe una nota visible concreta y el motivo administrativo; no compartas el cálculo privado.\n5. Guarda y confirma que el informe quedó aplicado y el personaje recibió exactamente los puntos aprobados. Nunca vuelvas a conceder una recompensa aplicada. No hace falta pedir a Admin que sume los puntos de un entrenamiento ordinario.","links":["training","sheets"]},"Incidencias con entrenamientos ya aprobados":{"old":"Si encuentras un error en una recompensa aplicada, identifica el informe, personaje, puntos concedidos y motivo de la corrección. No envíes otro informe ni vuelvas a aprobar el mismo para compensarlo. Escala la incidencia por la guía de tags cuando no puedas resolverla.","oldMeta":{"group":"Entrenamientos","roles":[],"requires":["training:action:review","training:data:details"]},"drop":false,"title":"Incidencias con entrenamientos ya aprobados","answer":"Si detectas un error en un informe aplicado, anota personaje, informe, puntos otorgados, evidencia y corrección necesaria. No generes otro informe para compensarlo ni repitas la aprobación. Si puedes corregirlo mediante una función autorizada, registra el motivo y comprueba el resultado; en caso contrario sigue la guía de tags de tu rango.","links":["training"]},"Crear y editar entradas de catálogo":{"old":"Abre Catálogos y añade una entrada dentro de la categoría adecuada. Rellena nombre, descripción, imagen, requisitos y bloques de información. Si es exclusiva, selecciona raza y variante compatibles. Disponible desde la creación habilita la selección inicial; Asignar automáticamente concede la entrada al crear si corresponde. No disponible la retira de la selección. Guarda y comprueba el resultado.","oldMeta":{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:contentEdit"]},"drop":false,"title":"Crear y editar entradas de catálogo","answer":"Abre Catálogos, elige la categoría y crea o edita la entrada. Añade nombre, descripción, imagen y bloques informativos. Para una habilidad exclusiva, selecciona raza y variante compatibles. Disponible desde creación permite elegirla inicialmente; Asignar automáticamente la concede cuando corresponda. Desactiva la disponibilidad inicial si debe obtenerse en rol. Configura los requisitos de desbloqueo y comprueba el resultado. No utilices la categoría Tipos de ki para controles o técnicas.","links":["catalogs"]},"Configurar una raza y sus variantes":{"old":"En Catálogos abre la gestión de razas. Indica nombre, descripción, imagen, magia inicial y máxima, y variantes. Cada línea de variante sigue el formato nombre | máximo inicial | bonus sumable | magia extra. Los valores no deben ser negativos; deja sin habilitar las razas cuyos límites estén pendientes. Marca exclusiva o no disponible cuando corresponda.","oldMeta":{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:raceConfig"]},"drop":false,"title":"Configurar una raza y sus variantes","answer":"En Catálogos, abre Razas y elige Añadir o Editar. Define nombre, descripción, imagen, magia inicial y máxima, disponibilidad, exclusividad y variantes. Cada línea de variante sigue el formato nombre | máximo inicial | bonus sumable | magia extra. Los valores deben ser válidos y no negativos. Las razas pendientes de definir deben permanecer no disponibles. Revisa el selector de creación y las habilidades vinculadas antes de habilitarla.","links":["catalogs","sheets"]},"Configurar tipos de ki y técnicas raciales":{"old":"En la configuración de raza puedes limitar sus tipos de ki iniciales a entradas compatibles. En Catálogos, utiliza la categoría Tipos de ki y la disponibilidad inicial para definir el selector único. En técnicas raciales, vincula la raza y, si procede, la variante. Usa la asignación automática solo para habilidades iniciales reales. No clasifiques los controles de ki como tipos de energía.","oldMeta":{"group":"Catálogos y razas","roles":[],"requires":["catalogs:action:raceConfig","catalogs:action:contentEdit"]},"drop":false,"title":"Configurar tipos de ki y técnicas raciales","answer":"Edita los tipos iniciales permitidos de la raza; en cada variante, comprueba si existe una restricción adicional. Las entradas de Tipos de ki definen las opciones de un selector único. Los Androides no reciben necesariamente Ki infinito: la habilidad de energía ilimitada solo corresponde al tipo compatible. Las técnicas raciales y los controles se configuran como entradas distintas, vinculadas a su raza/variante. Activa la asignación automática únicamente para habilidades innatas reales.","links":["catalogs"]},"Configurar las recompensas del Spin":{"old":"En Zenis e inventario busca Configuración de recompensas Spin. Pulsa Añadir premio, selecciona un objeto del catálogo, rareza, cantidad y si es único. Configura premios para todas las rarezas antes de habilitar la ruleta. Revisa el precio y máximo de tiradas en sus reglas. Las tiradas normales descuentan el coste y entregan el premio automáticamente; no requieren intervención.","oldMeta":{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinRewardEdit","settings:action:ruleConfig"]},"drop":false,"title":"Configurar las recompensas del Spin","answer":"En Zenis e inventario, abre Configuración de recompensas Spin. Añade premios vinculados a objetos del catálogo, define rareza, cantidad y unicidad. Comprueba la disponibilidad de premios por rareza antes de activar el Spin. El coste y el límite de tiradas se ajustan en Configuración de reglas. Los premios ordinarios son automáticos; no alteres el saldo para compensar una tirada sin un procedimiento autorizado.","links":["wallet","settings","catalogs"]},"Revisar premios legendarios":{"old":"En Zenis e inventario localiza Recompensas pendientes. Abre el premio legendario, comprueba el personaje, objeto y circunstancias de la tirada. Selecciona Aprobada o Rechazada e indica el motivo. Si apruebas, se incorpora al inventario; no lo añadas manualmente otra vez. Si no corresponde resolverlo con tus permisos, sigue la guía de escalado.","oldMeta":{"group":"Economía","roles":[],"requires":["wallet:data:content","spin:action:spinApprove"]},"drop":false,"title":"Revisar premios legendarios","answer":"En Zenis e inventario, abre Recompensas pendientes y revisa el objeto legendario, personaje, rareza y contexto de la tirada. Comprueba que el resultado corresponde a una tirada registrada y cumple el reglamento. Aprueba o rechaza el premio con motivo; verifica el resultado. No es necesario pedir autorización a un rango superior para una revisión ordinaria que tus permisos permiten. Esta revisión no equivale a editar libremente un inventario.","links":["wallet"]},"Cambiar moneda y límites por usuario":{"old":"En Configuración edita el nombre de la moneda y los límites de cada tipo de registro. Define el máximo total, máximo por periodo y duración del periodo según la necesidad. Guarda con motivo. Los valores de límite cero representan ausencia de ese límite. No reduzcas límites sin valorar los registros existentes.","oldMeta":{"group":"Configuración","roles":[],"requires":["settings:action:settingsSave"]},"drop":false,"title":"Cambiar moneda y límites por usuario","answer":"En Configuración cambia el nombre de la moneda o los límites de cada registro. Total controla la cantidad acumulada; Por periodo limita la cantidad en un intervalo de horas. Cero desactiva el límite correspondiente. Evita valores que bloqueen accidentalmente a los jugadores. Escribe el motivo y guarda; los campos de solo consulta no deben modificarse.","links":["settings"]},"Configurar las reglas del rol":{"old":"En Configuración pulsa Configurar reglas. Ajusta el equilibrio de reparto si se utiliza, el límite de estadísticas y el divisor de ganancias. Introduce valores coherentes y el motivo; verifica el efecto sobre los cálculos. No actives el equilibrio si el reglamento lo mantiene desactivado.","oldMeta":{"group":"Configuración","roles":[],"requires":["settings:action:ruleConfig"]},"drop":false,"title":"Configurar las reglas del rol","answer":"En Configuración, pulsa Configurar reglas. Ajusta el equilibrio solo si se decide activarlo, el límite y divisor de ganancias, los umbrales de comparación, y coste/límite de Spin. Contrasta cada valor con el reglamento y la saga vigente. No inventes parámetros pendientes. Comprueba que los cambios afectan al cálculo esperado antes de aprobar nuevos informes.","links":["settings","sagas","compare"]},"Configurar talentos y probabilidades":{"old":"En Configuración abre Configurar talentos. Añade o elimina talentos, edita sus nombres y descripciones, y asigna probabilidades entre 0 y 100. La suma debe ser exactamente 100 %. Los resultados ya guardados no se vuelven a tirar por cambiar la configuración.","oldMeta":{"group":"Configuración","roles":[],"requires":["settings:action:talentConfig"]},"drop":false,"title":"Configurar talentos y probabilidades","answer":"En Configuración, abre Configurar talentos. Crea, edita o elimina talentos, sus descripciones y pesos de aparición. Comprueba la distribución: la probabilidad efectiva depende de los pesos relativos, y un peso cero impide que salga. No cambies talentos ya elegidos para compensar un sorteo sin una intervención autorizada. Revisa el resultado de la elección tras crear una ficha.","links":["settings"]},"Crear y ordenar categorías y páginas":{"old":"Abre Organización y páginas. Añade categorías de navegación para agrupar apartados, crea páginas y utiliza los controles de movimiento para ordenar categorías y páginas o cambiarlas de grupo. Comprueba la navegación con el acceso que corresponda. No crees un apartado duplicado si puedes reorganizar uno existente.","oldMeta":{"group":"Organización","roles":[],"requires":["categories:action:navGroupEdit","categories:action:navPageMove","categories:action:navGroupMove"]},"drop":false,"title":"Crear y ordenar categorías y páginas","answer":"En Organización y páginas, crea categorías para agrupar apartados del menú. Usa las flechas para moverlos y Editar para cambiar de nombre o categoría. Crea una página solo cuando exista contenido propio que lo justifique. Comprueba que no dupliques secciones existentes y revisa el resultado en el menú lateral.","links":["categories"]},"Editar información de una página":{"old":"En Organización y páginas selecciona la página que quieras crear o editar. Define su nombre y descripción, añade bloques de título, texto, lista, imagen o enlace, y ordénalos. Comprueba el contenido y el acceso antes de guardarlo.","oldMeta":{"group":"Organización","roles":[],"requires":["categories:action:navPageEdit"]},"drop":false,"title":"Editar información de una página","answer":"En Organización y páginas crea una página o pulsa Contenido en una existente. Añade títulos, texto, listas, imágenes y enlaces mediante bloques; reordena o elimina los que sobren. Guarda y abre la página desde el menú para revisar el resultado. Los usuarios solo verán los bloques permitidos. No insertes contraseñas ni información privada en una página pública.","links":["categories"]},"Modificar el molde de un formulario":{"old":"Abre Moldes de formularios y selecciona el formulario. Añade apartados y campos, define tipo, opciones, ayuda y obligatoriedad. En las fichas decide si el campo lo rellena el jugador, solo durante la creación, o el Staff. Los cambios se aplican a fichas existentes; los campos nuevos quedan vacíos hasta rellenarlos. No sustituyas campos de sistema por textos libres.","oldMeta":{"group":"Organización","roles":[],"requires":["schemas:action:sectionEdit","schemas:action:fieldEdit"]},"drop":false,"title":"Modificar el molde de un formulario","answer":"En Moldes de formularios elige Fichas o Razas custom. Añade apartados y campos y configura tipo, opciones, ayuda y obligatoriedad. En fichas distingue Jugador (creación y edición), Solo creación y Staff (no se muestra al crear/editar como jugador). Usa selectores para listas cerradas y catálogo para referencias gestionadas. Comprueba los cambios con una ficha existente y un formulario nuevo; no elimines campos necesarios para las estadísticas o la raza.","links":["schemas","sheets","races"]},"Consultar roles y permisos":{"old":"En Roles y permisos pulsa Consultar permisos junto al rol. Acceso permite abrir una página; Datos visibles determina qué información muestra; Mostrar controla los botones; Ejecutar permite realizar las acciones autorizadas. Utiliza esta consulta para identificar quién puede resolver una petición.","oldMeta":{"group":"Equipo","roles":[],"requires":["roles:action:roleView"]},"drop":false,"title":"Consultar roles y permisos","answer":"Abre Roles y permisos y pulsa Consultar permisos en un rol. Acceso abre la página; Datos visibles limita la información; Mostrar decide si aparece el botón; Ejecutar autoriza la acción. Un botón visible no garantiza permiso para usarlo. Las cuentas con varios roles pueden reunir permisos de varios. Si detectas un permiso incorrecto, documenta el rol, página, dato o acción exacta y sigue tu guía de escalado.","links":["roles"]},"Crear, editar y ordenar roles":{"old":"En Roles y permisos crea o edita un rol no protegido. Define su nombre, color y jerarquía; configura acceso, datos, permisos generales y acciones individuales. La visibilidad no equivale a permiso de ejecución. Prueba cada cambio con una cuenta de ese rango. No concedas capacidades fuera de la responsabilidad del rango.","oldMeta":{"group":"Equipo","roles":[],"requires":["roles:action:roleEdit","roles:action:roleMove"]},"drop":false,"title":"Crear, editar y ordenar roles","answer":"Crea o edita un rol no protegido. Define nombre, color y posición en la jerarquía. Configura primero acceso a cada página, después datos visibles y permisos de ejecución, y por último botones individuales. Aplica el mínimo acceso necesario para sus tareas. Comprueba los permisos desde Consultar permisos antes de asignarlo. No utilices roles alternativos para saltarte una restricción reservada al Owner.","links":["roles","users"]},"Consultar y filtrar registros":{"old":"Abre Registros. Combina fecha y hora inicial/final, autor, tipo de acción, módulo y búsqueda por texto. Abre Antes / después para consultar los cambios de datos autorizados. Comprueba el autor, fecha, motivo y campos afectados al investigar una incidencia.","oldMeta":{"group":"Auditoría","roles":[],"requires":["logs:data:content","logs:data:detail","logs:action:logView"]},"drop":false,"title":"Consultar y filtrar registros","answer":"En Registros, combina los filtros de fecha/hora inicial y final, usuario, tipo de acción, módulo y búsqueda de texto. Abre Antes / después para identificar el dato que cambió, su autor y motivo. No interpretes un registro aislado sin revisar operaciones posteriores. Los detalles protegidos no están disponibles para todos los rangos.","links":["logs"]},"Consultar datos y consumo":{"old":"En Datos y consumo revisa las lecturas, escrituras y eliminaciones diarias estimadas y los registros almacenados por colección. Compara con los límites gratuitos mostrados; son estimaciones locales, no cifras reales de Firebase ni importes monetarios. Investiga aumentos de actividad antes de aplicar medidas.","oldMeta":{"group":"Auditoría","roles":[],"requires":["data:data:content"]},"drop":false,"title":"Consultar datos y consumo","answer":"En Datos y consumo, consulta los contadores estimados de lecturas, escrituras y eliminaciones diarias y la cantidad de registros por colección. La barra compara con el límite gratuito configurado en la demo; no es una factura ni una medición real de Firebase. Si el uso es anormal, identifica el módulo y revisa los límites o actividad autorizada.","links":["data"]},"Restaurar una copia":{"old":"Antes de restaurar, conserva una copia actual y comprueba la fecha y origen del archivo. Selecciona el archivo JSON y revisa el aviso que indica qué datos se reemplazarán o conservarán. Confirma solo si entiendes el alcance; la operación puede cerrar la sesión.","oldMeta":{"group":"Auditoría","roles":[],"requires":["backups:action:restore"]},"drop":false,"title":"Restaurar una copia","answer":"Antes de restaurar, descarga una copia del estado actual y verifica el origen y versión del JSON. Selecciona el archivo, lee qué datos se reemplazan y confirma solo si procede. Una restauración parcial conserva las cuentas y los datos protegidos que tu rol no puede modificar. Tras restaurar, revisa la coherencia de fichas, inventarios, configuración y permisos. No uses una copia para eludir restricciones.","links":["backups"]}};

