 '¿Cómo informo de un error en la web?':['@bug'],
 '¿Cómo cambio mi contraseña?':['profile'],
 '¿Cómo reporto un error?':['@bug'],
 'Previsualizar el manual de otro rango':['faqStaff','faqUser']
