// Shared weighted draw configuration and integrity checks. No extra storage or polling.
const config083=(value,defaults={count:1,repeat:true})=>({count:value?.count??defaults.count,repeat:value?.repeat??defaults.repeat});
function poolIssue083(rows,config){
 if(!Number.isSafeInteger(config.count)||config.count<1||config.count>20||typeof config.repeat!=='boolean')return 'Número de tiradas inválido (1–20).';
 if(!Array.isArray(rows)||!rows.length)return 'No hay resultados disponibles.';
 if(rows.some(x=>typeof x.weight!=='number'||!Number.isFinite(x.weight)||x.weight<0||x.weight>100))return 'Hay probabilidades vacías o fuera de 0–100.';
 const sum=rows.reduce((n,x)=>n+x.weight,0),positive=rows.filter(x=>x.weight>0).length;
 if(Math.abs(sum-100)>1e-6)return `Las probabilidades suman ${Number(sum.toFixed(6))}% (deben sumar 100%).`;
 if(!positive)return 'No hay resultados con probabilidad positiva.';
 if(!config.repeat&&positive<config.count)return `Hay ${positive} resultados posibles para ${config.count} tiradas sin repeticiones.`;
 return '';
}
function draw083(rows,config,random=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296){
 const issue=poolIssue083(rows,config);if(issue)throw Error(issue);let available=rows.filter(x=>x.weight>0),out=[];
 for(let i=0;i<config.count;i++){let total=available.reduce((n,x)=>n+x.weight,0),v=random()*total,index=available.findIndex(x=>(v-=x.weight)<0);if(index<0)index=available.length-1;out.push(available[index].id);if(!config.repeat)available.splice(index,1);}
 return out;
}
function racePool083(r,secondary=false){let rows=(r?.variants||[]).filter(v=>v.cap!=null&&!v.unavailable&&!!v.secondary===secondary&&v.spin083!==false).map(v=>({id:v.id,weight:v.weight}));if(secondary&&r.secondaryNoneWeight!==0)rows.unshift({id:'',weight:r.secondaryNoneWeight??null});return rows;}
function raceIssues083(r){let issues=[];if(r.unavailable)return issues;for(let secondary of [false,true]){let mode=secondary?r.secondaryMode:r.variantMode;if(mode!=='random')continue;let rows=racePool083(r,secondary);if(!secondary&&(r.variants||[]).filter(v=>v.cap!=null&&!v.unavailable&&!v.secondary).length===1&&!r.variantSpin083)continue;let issue=poolIssue083(rows,config083(secondary?r.secondarySpin083:r.variantSpin083));if(issue)issues.push({code:secondary?'secondary':'primary',message:(secondary?'Subraza secundaria: ':'Subraza principal: ')+issue});}return issues;}

