function secondary154(r){return (r?.variants||[]).filter(v=>v.secondary&&!v.unavailable&&v.cap!=null)}function needsReservation154(r){return random154(r)||r?.secondaryMode==='random'}function reservationData154(r){return me?.variantReservations?.[r?.id]}function reservation154(r){return primary154(r).find(x=>x.id===reservationData154(r)?.variant);}function effective154(v,secondary){return !v?null:secondary?{...v,secondaryId:secondary.id,name:v.name+' · '+secondary.name,cap:Math.max(v.cap,secondary.cap),bonus:(+v.bonus||0)+(+secondary.bonus||0),extraMagic:(+v.extraMagic||0)+(+secondary.extraMagic||0)}:v;}
function variantReserve(raceId){if(!allow('sheets','create')||!withinLimit('sheets'))throw Error('No puedes crear más fichas.');let race=record('raceDefinitions',raceId);if(!raceSelectable(race,null))throw Error('Raza no disponible.');if(!needsReservation154(race))throw Error('Esta raza no requiere tirada.');if(reservationData154(race))throw Error('Ya tienes una tirada reservada para esta raza.');let issues=raceIssues083(race);if(issues.length)throw Error('El Staff debe revisar las probabilidades: '+issues.map(x=>x.message).join(' '));let variants=random154(race)?draw083(racePool083(race),config083(race.variantSpin083)):[],secondaries=race.secondaryMode==='random'?draw083(racePool083(race,true),config083(race.secondarySpin083)):[];return mutate(['users'],a=>{let u=a.find(x=>x.id===me.id);u.variantReservations??={};u.variantReservations[race.id]={variant:variants[0]||'',secondary:secondaries[0]||'',variants,secondaries,at:now()};},'Tiradas raciales reservadas · '+race.name,'',false);}
